import * as React from "react";
import { mount, ReactWrapper } from "enzyme";
import { RoomMember } from "matrix-js-sdk/src/models/room-member";
import { MatrixEvent } from "matrix-js-sdk/src/models/event";

import { createTestClient, mkEvent, mkStubRoom, stubClient } from "../../../test-utils";
import MessageComposer from "../../../../src/components/views/rooms/MessageComposer";
import MatrixClientContext from "../../../../src/contexts/MatrixClientContext";
import { MatrixClientPeg } from "../../../../src/MatrixClientPeg";
import RoomContext from "../../../../src/contexts/RoomContext";
import { IRoomState } from "../../../../src/components/structures/RoomView";
import ResizeNotifier from "../../../../src/utils/ResizeNotifier";
import { RoomPermalinkCreator } from "../../../../src/utils/permalinks/Permalinks";

describe("MessageComposer", () => {
    stubClient();
    const cli = createTestClient();
    const room = mkStubRoom("!roomId:server", "Room 1", cli);

    it("Renders a SendMessageComposer and MessageComposerButtons by default", () => {
        const wrapper = wrapAndRender({ room });

        expect(wrapper.find("SendMessageComposer")).toHaveLength(1);
        expect(wrapper.find("MessageComposerButtons")).toHaveLength(1);
    });

    it("Does not render a SendMessageComposer or MessageComposerButtons when user has no permission", () => {
        const wrapper = wrapAndRender({ room }, false);

        expect(wrapper.find("SendMessageComposer")).toHaveLength(0);
        expect(wrapper.find("MessageComposerButtons")).toHaveLength(0);
        expect(wrapper.find(".mx_MessageComposer_noperm_error")).toHaveLength(1);
    });

    it("Does not render a SendMessageComposer or MessageComposerButtons when room is tombstoned", () => {
        const wrapper = wrapAndRender({ room }, true, mkEvent({
            event: true,
            type: "m.room.tombstone",
            room: room.roomId,
            user: "@user1:server",
            skey: "",
            content: {},
            ts: Date.now(),
        }));

        expect(wrapper.find("SendMessageComposer")).toHaveLength(0);
        expect(wrapper.find("MessageComposerButtons")).toHaveLength(0);
        expect(wrapper.find(".mx_MessageComposer_roomReplaced_header")).toHaveLength(1);
    });
});

function wrapAndRender(props = {}, canSendMessages = true, tombstone?: MatrixEvent): ReactWrapper {
    const mockClient = MatrixClientPeg.get();
    const roomId = "myroomid";
    const room: any = {
        currentState: undefined,
        roomId,
        client: mockClient,
        getMember: function(userId: string): RoomMember {
            return new RoomMember(roomId, userId);
        },
    };

    const roomState = {
        room, canSendMessages, tombstone,
    } as unknown as IRoomState;

    const defaultProps = {
        room,
        resizeNotifier: new ResizeNotifier(),
        permalinkCreator: new RoomPermalinkCreator(room),
    };

    return mount(
        <MatrixClientContext.Provider value={mockClient}>
            <RoomContext.Provider value={roomState}>
                <MessageComposer {...defaultProps} {...props} />
            </RoomContext.Provider>
        </MatrixClientContext.Provider>,
    );
}

        dis.dispatch<ComposerInsertPayload>({
            action: Action.ComposerInsert,
            text: emoji,
            timelineRenderingType: this.context.timelineRenderingType,
        });
        return true;
    };

    private sendMessage = async () => {
        if (this.state.haveRecording && this.voiceRecordingButton.current) {
            // There shouldn't be any text message to send when a voice recording is active, so
            // just send out the voice recording.
            await this.voiceRecordingButton.current?.send();
            return;
        }

        this.messageComposerInput.current?.sendMessage();
    };

    private onChange = (model: EditorModel) => {
        this.setState({
            isComposerEmpty: model.isEmpty,
        });
    };

    private onVoiceStoreUpdate = () => {
        this.updateRecordingState();
    };

    private updateRecordingState() {
        this.voiceRecording = VoiceRecordingStore.instance.getActiveRecording(this.props.room.roomId);
        if (this.voiceRecording) {
            // If the recording has already started, it's probably a cached one.
            if (this.voiceRecording.hasRecording && !this.voiceRecording.isRecording) {
                this.setState({ haveRecording: true });
            }

            // Note: Listeners for recording states are set by the `this.voiceRecording` setter.
        } else {
            this.setState({ haveRecording: false });
        }
    }

    private onRecordingStarted = () => {
        // update the recording instance, just in case
        this.voiceRecording = VoiceRecordingStore.instance.getActiveRecording(this.props.room.roomId);
        this.setState({
            haveRecording: !!this.voiceRecording,
        });
    };

    private onRecordingEndingSoon = ({ secondsLeft }) => {
        this.setState({ recordingTimeLeftSeconds: secondsLeft });
        setTimeout(() => this.setState({ recordingTimeLeftSeconds: null }), 3000);
    };

    private setStickerPickerOpen = (isStickerPickerOpen: boolean) => {
        this.setState({
            isStickerPickerOpen,
            isMenuOpen: false,
        });
    };

    private toggleStickerPickerOpen = () => {
        this.setStickerPickerOpen(!this.state.isStickerPickerOpen);
    };

    private toggleButtonMenu = (): void => {
        this.setState({
            isMenuOpen: !this.state.isMenuOpen,
        });
    };

    public render() {
        const controls = [
            this.props.e2eStatus ?
                <E2EIcon key="e2eIcon" status={this.props.e2eStatus} className="mx_MessageComposer_e2eIcon" /> :
                null,
        ];

        let menuPosition: AboveLeftOf | undefined;
        if (this.ref.current) {
            const contentRect = this.ref.current.getBoundingClientRect();
            menuPosition = aboveLeftOf(contentRect);
        }

        const canSendMessages = this.context.canSendMessages && !this.context.tombstone;
        if (canSendMessages) {
            controls.push(
                <SendMessageComposer
                    ref={this.messageComposerInput}
                    key="controls_input"
                    room={this.props.room}
                    placeholder={this.renderPlaceholderText()}
                    permalinkCreator={this.props.permalinkCreator}
                    relation={this.props.relation}
                    replyToEvent={this.props.replyToEvent}
                    onChange={this.onChange}
                    disabled={this.state.haveRecording}
                    toggleStickerPickerOpen={this.toggleStickerPickerOpen}
                />,
            );

            controls.push(<VoiceRecordComposerTile
                key="controls_voice_record"
                ref={this.voiceRecordingButton}
                room={this.props.room} />);
        } else if (this.context.tombstone) {
            const replacementRoomId = this.context.tombstone.getContent()['replacement_room'];

            const continuesLink = replacementRoomId ? (
                <a href={makeRoomPermalink(replacementRoomId)}
                    className="mx_MessageComposer_roomReplaced_link"
                    onClick={this.onTombstoneClick}
                >
                    { _t("The conversation continues here.") }
                </a>
            ) : '';

            controls.push(<div className="mx_MessageComposer_replaced_wrapper" key="room_replaced">
                <div className="mx_MessageComposer_replaced_valign">
                    <img className="mx_MessageComposer_roomReplaced_icon"
                        src={require("../../../../res/img/room_replaced.svg").default}
                    />
                    <span className="mx_MessageComposer_roomReplaced_header">
                        { _t("This room has been replaced and is no longer active.") }
                    </span><br />
                    { continuesLink }
                </div>
            </div>);
        } else {
            controls.push(
                <div key="controls_error" className="mx_MessageComposer_noperm_error">
                    { _t('You do not have permission to post to this room') }
                </div>,
            );
        }

        let recordingTooltip;
        const secondsLeft = Math.round(this.state.recordingTimeLeftSeconds);
        if (secondsLeft) {
            recordingTooltip = <Tooltip
                label={_t("%(seconds)ss left", { seconds: secondsLeft })}
                alignment={Alignment.Top}
            />;
        }

        const threadId = this.props.relation?.rel_type === THREAD_RELATION_TYPE.name
            ? this.props.relation.event_id
            : null;

        controls.push(
            <Stickerpicker
                room={this.props.room}
                threadId={threadId}
                isStickerPickerOpen={this.state.isStickerPickerOpen}
                setStickerPickerOpen={this.setStickerPickerOpen}
                menuPosition={menuPosition}
                key="stickers"
            />,
        );

        const showSendButton = !this.state.isComposerEmpty || this.state.haveRecording;

        const classes = classNames({
            "mx_MessageComposer": true,
            "mx_GroupLayout": true,
            "mx_MessageComposer--compact": this.props.compact,
            "mx_MessageComposer_e2eStatus": this.props.e2eStatus != undefined,
        });

        return (
            <div className={classes} ref={this.ref}>
                { recordingTooltip }
                <div className="mx_MessageComposer_wrapper">
                    <ReplyPreview
                        replyToEvent={this.props.replyToEvent}
                        permalinkCreator={this.props.permalinkCreator} />
                    <div className="mx_MessageComposer_row">
                        { controls }
                        { canSendMessages && <MessageComposerButtons
                            addEmoji={this.addEmoji}
                            haveRecording={this.state.haveRecording}
                            isMenuOpen={this.state.isMenuOpen}
                            isStickerPickerOpen={this.state.isStickerPickerOpen}
                            menuPosition={menuPosition}
                            relation={this.props.relation}
                            onRecordStartEndClick={() => {
                                this.voiceRecordingButton.current?.onRecordStartEndClick();
                                if (this.context.narrow) {
                                    this.toggleButtonMenu();
                                }
                            }}
                            setStickerPickerOpen={this.setStickerPickerOpen}
                            showLocationButton={!window.electron}
                            showPollsButton={this.state.showPollsButton}
                            showStickersButton={this.state.showStickersButton}
                            toggleButtonMenu={this.toggleButtonMenu}
                        /> }
                        { showSendButton && (
                            <SendButton
                                key="controls_send"
                                onClick={this.sendMessage}
                                title={this.state.haveRecording ? _t("Send voice message") : undefined}
                            />
                        ) }
                    </div>
                </div>
            </div>
        );
    }
}

